def completer_empreintes(apps, schema_editor):
    """
    Prépare la contrainte d'unicité « image_unique_par_client » :
      1. calcule l'empreinte SHA-256 des images qui n'en avaient pas
         (images ajoutées depuis le back-office en V1) ;
      2. si deux images actives d'un même client ont la même empreinte
         (doublon historique), la plus récente est renommée pour ne pas
         bloquer la migration — aucune donnée n'est supprimée.
    """
    Image = apps.get_model("core", "Image")
    vues = set()
    for img in Image.objects.order_by("pk").iterator():
        empreinte = img.hash_fichier
        if not empreinte:
            h = hashlib.sha256()
            try:
                with img.fichier.open("rb") as f:
                    for bloc in iter(lambda f=f: f.read(1 << 20), b""):
                        h.update(bloc)
                empreinte = h.hexdigest()
            except (OSError, ValueError):
                empreinte = f"fichier-absent-{img.pk}"
        if not img.is_deleted:
            if (img.client_id, empreinte) in vues:
                empreinte = f"doublon-historique-{img.pk}"
            vues.add((img.client_id, empreinte))
        if empreinte != img.hash_fichier:
            Image.objects.filter(pk=img.pk).update(hash_fichier=empreinte)


